/**
 * @summary Create a new bill at checkout
 */
export const checkoutBodyItemsItemNameMax = 80;

export const checkoutBodyItemsItemPurchasePriceMin = 0;
export const checkoutBodyItemsItemPurchasePriceMax = 99999999.99;

export const checkoutBodyCustomerPhoneRegExp = new RegExp("^[0-9]{10}$");

export const CheckoutBody = zod.object({
  items: zod.array(
    zod
      .object({
        productId: zod
          .string()
          .optional()
          .describe("Catalogue product id. Omit on manual lines."),
        name: zod
          .string()
          .max(checkoutBodyItemsItemNameMax)
          .optional()
          .describe(
            "Manual lines only — the description printed on the receipt.",
          ),
        quantity: zod.number().int(),
        price: zod.number().describe("Effective per-unit selling price."),
        mrp: zod.number().optional().describe("Catalogue lines only."),
        purchasePrice: zod
          .number()
          .min(checkoutBodyItemsItemPurchasePriceMin)
          .max(checkoutBodyItemsItemPurchasePriceMax)
          .optional()
          .describe(
            "Per-unit cost typed by the cashier, stored on the sale line so profit reports net it against the price. REQUIRED on manual lines (no productId): checkout answers 400 naming the item when it is missing. 0 is a valid explicit value. Ignored on catalogue lines, whose cost is read from the product at checkout.",
          ),
      })
      .describe(
        "One bill line. Either a catalogue line (`productId`, optional `mrp`) or a manual \/ non-inventory line (`name` instead of `productId`, no stock movement). Exactly one of `productId` or `name` must be present.",
      ),
  ),
  paymentMode: zod
    .enum(["cash", "upi", "credit"])
    .describe(
      "Mode of payment. `credit` records the bill as unpaid (receivable) against the customer identified by `customerPhone`.",
    ),
  customerName: zod.string().optional(),
  customerPhone: zod
    .string()
    .regex(checkoutBodyCustomerPhoneRegExp)
    .describe(
      "Customer's 10-digit mobile number (bare digits, no +91). REQUIRED on every bill — checkout answers 400 without it. It is the key the customer ledger, credit collection and repeat-customer lookups use.",
    ),
  discount: zod
    .number()
    .optional()
    .describe("Raw discount value (e.g. 10 for 10% or 200 for ₹200)"),
  discountType: zod
    .enum(["percent", "amount"])
    .optional()
    .describe("How to interpret the discount value"),
});

export const CheckoutResponse = zod.object({
  bill: zod.object({
    id: zod.string(),
    billNumber: zod.number().int().optional(),
    totalAmount: zod.number(),
    amountPaid: zod
      .number()
      .describe("Cumulative amount collected against this bill."),
    paymentStatus: zod.enum(["paid", "partial", "unpaid"]),
    itemsCount: zod.number().int(),
    paymentMode: zod.string(),
    customerName: zod.string().nullish(),
    customerPhone: zod.string().nullish(),
    discount: zod.number().nullish(),
    discountType: zod.string().nullish(),
    createdAt: zod.string(),
  }),
  items: zod.array(
    zod.object({
      id: zod.string(),
      productId: zod.string(),
      productName: zod.string(),
      productSku: zod.string(),
      quantity: zod.number().int(),
      price: zod.number(),
      mrp: zod.number().nullish(),
      subtotal: zod.number(),
    }),
  ),
});

